import heapq
from collections import defaultdict

class DualHeap:
    def __init__(self, k):
        # max-heap for lower half, min-heap for upper half
        self.small = []  # max-heap (invert values)
        self.large = []  # min-heap
        self.delayed = defaultdict(int)  # value: count to remove later
        self.k = k
        self.small_size = 0  # number of valid (non-deleted) elements
        self.large_size = 0

    def prune(self, heap):
        # Remove the top element if it's marked for deletion
        while heap:
            num = -heap[0] if heap == self.small else heap[0]
            if self.delayed[num]:
                heapq.heappop(heap)
                self.delayed[num] -= 1
            else:
                break

    def balance(self):
        # Keep sizes within 1
        if self.small_size > self.large_size + 1:
            # Move from small to large
            val = -heapq.heappop(self.small)
            heapq.heappush(self.large, val)
            self.small_size -= 1
            self.large_size += 1
            self.prune(self.small)
        elif self.small_size < self.large_size:
            # Move from large to small
            val = heapq.heappop(self.large)
            heapq.heappush(self.small, -val)
            self.large_size -= 1
            self.small_size += 1
            self.prune(self.large)

    def insert(self, num):
        # Always push onto small, then rebalance to maintain ordering
        if not self.small or num <= -self.small[0]:
            heapq.heappush(self.small, -num)
            self.small_size += 1
        else:
            heapq.heappush(self.large, num)
            self.large_size += 1
        self.balance()

    def erase(self, num):
        # Mark for delayed removal
        self.delayed[num] += 1
        if self.small and num <= -self.small[0]:
            self.small_size -= 1
            if -self.small[0] == num:
                self.prune(self.small)
        else:
            self.large_size -= 1
            if self.large and self.large[0] == num:
                self.prune(self.large)
        self.balance()

    def get_median(self):
        if self.k % 2:  # odd k
            return float(-self.small[0])
        else:
            return (-self.small[0] + self.large[0]) / 2

def medianSlidingWindow(nums, k):
    if not nums or k == 0:
        return []
    dh = DualHeap(k)
    result = []
    for i in range(k):
        dh.insert(nums[i])
    result.append(dh.get_median())
    for i in range(k, len(nums)):
        dh.insert(nums[i])
        dh.erase(nums[i - k])
        result.append(dh.get_median())
    return result
